-- Fuente: https://github.com/gor3a/vehicle-makes-models
-- Data bajo ODbL 1.0; se usa el CSV compacto data/csv/makes-models.csv.
USE taller_db;

ON DUPLICATE KEY UPDATE make_group = VALUES(make_group);

ON DUPLICATE KEY UPDATE year_start = VALUES(year_start), year_end = VALUES(year_end);

-- Versiones generadas desde engines.csv para autocompletado local.
CREATE TEMPORARY TABLE IF NOT EXISTS vehicle_version_seed (
  make_name VARCHAR(120) NOT NULL,
  model_name VARCHAR(160) NOT NULL,
  version_name VARCHAR(260) NOT NULL
) ENGINE=InnoDB;
TRUNCATE TABLE vehicle_version_seed;

SELECT vm.id, seed.version_name
FROM vehicle_version_seed seed
JOIN vehicle_makes make ON LOWER(make.name) = LOWER(seed.make_name)
JOIN vehicle_models vm ON vm.make_id = make.id AND LOWER(vm.name) = LOWER(seed.model_name)
GROUP BY vm.id, seed.version_name
ON DUPLICATE KEY UPDATE name = VALUES(name);

DROP TEMPORARY TABLE vehicle_version_seed;
